const $=s=>document.querySelector(s);let dispatch={orders:[],riders:[]};
function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
async function api(path,options={}){const r=await fetch(path,{headers:{'Content-Type':'application/json'},...options});const d=await r.json();if(!r.ok)throw new Error(d.error||'Request failed');return d}
function money(n){return `₹${Math.round(n)}`}
function riderOptions(selected){return dispatch.riders.filter(r=>r.availability!=='offline'||r.id===selected).map(r=>`<option value="${r.id}" ${r.id===selected?'selected':''}>${r.name} · ${r.availability}</option>`).join('')}
function render(){const online=dispatch.riders.filter(r=>r.availability!=='offline').length;$('#ridersKpi').textContent=online;$('#dispatchTable').innerHTML=dispatch.orders.length?dispatch.orders.map(o=>`<tr><td><b>${o.id}</b></td><td>${o.customer_name}</td><td><span class="status ${o.status==='Delivered'?'delivered':''}">${o.status}</span></td><td>${o.eta_minutes} min</td><td>${money(o.total)}</td><td><div class="assign-row"><select data-rider-for="${o.id}"><option value="">Choose driver</option>${riderOptions(o.rider_id)}</select><button data-assign="${o.id}">${o.rider_id?'Reassign':'Assign'}</button></div></td></tr>`).join(''):'<tr><td colspan="6">No open orders.</td></tr>';$('#riderList').innerHTML=dispatch.riders.map(r=>`<div class="rider-row"><div class="avatar">${r.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div><b>${r.name}</b><small>${r.vehicle} · ★ ${r.rating}${r.current_order_id?' · '+r.current_order_id:''}</small></div><span class="availability ${r.availability}">${r.availability}</span></div>`).join('');const points=dispatch.riders.filter(r=>r.latitude!=null).map(r=>({lat:Number(r.latitude),lng:Number(r.longitude),label:'D',title:r.name}));if(points.length)TTB.renderMap('adminMap',points)}
async function load(){try{const [d,i,n]=await Promise.all([api('/api/v1/dispatch'),api('/api/v1/insights'),api('/api/v1/notifications')]);dispatch=d;render();$('#ordersKpi').textContent=i.orders;$('#openKpi').textContent=i.open_orders;$('#revenueKpi').textContent=money(i.revenue);$('#eventList').innerHTML=(n.notifications||[]).slice(0,8).map(x=>`<div class="notice">${x.message}<small>${x.channel} · ${new Date(x.created_at).toLocaleTimeString()}</small></div>`).join('')||'<p class="subtle">No notifications yet.</p>';$('#lastUpdated').textContent='Updated '+new Date().toLocaleTimeString()}catch(e){toast(e.message)}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-assign]');if(!b)return;const select=document.querySelector(`[data-rider-for="${b.dataset.assign}"]`);if(!select.value)return toast('Choose an online driver');try{await api(`/api/v1/orders/${b.dataset.assign}/assign`,{method:'POST',body:JSON.stringify({rider_id:select.value})});toast('Delivery assigned');load()}catch(err){toast(err.message)}});
$('#refresh').onclick=load;$('#testNotice').onclick=async()=>{try{await api('/api/v1/notifications/test',{method:'POST'});toast('Test notification queued');load()}catch(e){toast(e.message)}};$('#dailyReport').onclick=e=>{if(!TTB.apiBase){e.preventDefault();return toast('Connect the hosted API to download live reports')}e.currentTarget.href=`${TTB.apiBase}/api/v1/reports/daily.csv`};load();setInterval(load,8000);
